const fs = require('node:fs'), path = require('node:path'), vm = require('node:vm'), assert = require('node:assert/strict');
const html = fs.readFileSync(process.argv[2] || path.join(__dirname, '..', 'index.html'), 'utf8'), box = vm.createContext({});
for (const m of [...html.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g)].slice(0, 2)) vm.runInContext(m[1], box);
const E = box.Yiwu, C = box.YiwuComputer, fixture = require('./computer-king-repetition-fixture.json'), copy = x => JSON.parse(JSON.stringify(x));
const same = (a, b) => a.type === b.type && a.id === b.id && a.x === b.x && a.y === b.y;
function state(row, rotated) {
  let s; for (const [op, ...args] of row.commands) {if (op === 'create') s = E.create(...args); else E[op](s, ...args);}
  assert.equal(s.phase, 'board'); assert.equal(s.ply + 1, row.ply);
  if (rotated) {
    s.turn = E.OTHER[s.turn]; for (const p of s.pieces) {p.side = E.OTHER[p.side]; p.x = 8 - p.x; p.y = 9 - p.y;}
    s.repetitions = Object.fromEntries(Object.entries(s.repetitions).map(([key, n]) => {const [turn, ps] = JSON.parse(key); return [JSON.stringify([E.OTHER[turn], ps.map(([id, x, y, ...rest]) => [id, 8 - x, 9 - y, ...rest])]), n];}));
  }
  return s;
}
function safeExits(s, side) {
  const king = s.pieces.find(p => p.side === side && p.kind === 'king');
  return E.moves(s, king).filter(m => !E.at(s, m.x, m.y)).filter(m => {
    const next = copy(s); next.turn = side; E.move(next, king.id, m.x, m.y);
    return next.phase === 'ended' ? next.winner !== E.OTHER[side] : !next.pieces.some(p => p.side !== side && E.canMove(next, p, m.x, m.y) && !C.battleOutlook(next, E.context(next, p, E.get(next, king.id))).counters.length);
  });
}
let cases = 0, samples = 0;
for (const row of fixture.cases) for (const rotated of [false, true]) {
  const s = state(row, rotated), original = JSON.stringify(s), transform = a => rotated ? {...a, x: 8 - a.x, y: 9 - a.y} : a, safe = transform(row.safe), danger = transform(row.danger);
  const ranked = copy(C.rankedActions(s)); assert(same(ranked[0], safe)); assert(ranked.find(a => same(a, safe)).score > ranked.find(a => same(a, danger)).score + 1.2);
  const unvisited = copy(s); unvisited.repetitions = {};
  assert(Math.abs(ranked.find(a => same(a, safe)).score - C.rankedActions(unvisited).find(a => same(a, safe)).score) < 1e-8, '必要防守不再受阵形重复扣分');
  for (const difficulty of ['standard', 'practice']) for (const roll of [0, .25, .5, .75, .999999]) {
    const action = C.board(s, () => roll, difficulty), next = copy(s); assert(same(action, safe)); E.move(next, action.id, action.x, action.y);
    assert.equal(next.phase, 'board'); assert(safeExits(next, s.turn).length); assert(!C.kingLostNext(next, s.turn)); samples++;
  }
  const mirror = C.rankedActions(state(row, !rotated));
  for (const a of ranked) {const b = mirror.find(b => same(b, {...a, x: 8 - a.x, y: 9 - a.y})); assert(b); assert(Math.abs(a.score - b.score) < 1e-8);}
  for (const kind of ['quiet', 'repetition']) {
    const next = copy(s), end = copy(s); E.move(end, safe.id, safe.x, safe.y);
    if (kind === 'quiet') next.quiet = E.DRAW.quiet - 1; else next.repetitions[E.key(end)] = E.DRAW.repetitions - 1;
    const before = JSON.stringify(next); assert(Number.isFinite(C.rankedActions(next).find(a => same(a, safe)).score)); assert.equal(JSON.stringify(next), before);
    E.move(next, safe.id, safe.x, safe.y); assert.equal(next.phase, 'ended'); assert.equal(next.winner, 'draw');
  }
  assert.equal(JSON.stringify(s), original); assert.deepEqual(copy(C.rankedActions(s)), ranked); cases++;
}
const quiet = E.create('attrition'), action = {type: 'move', id: 'hero', x: 4, y: 6}, visited = copy(quiet); E.move(visited, action.id, action.x, action.y);
const score = C.rankedActions(quiet).find(a => same(a, action)).score; quiet.repetitions[E.key(visited)] = 1;
assert(Math.abs(score - C.rankedActions(quiet).find(a => same(a, action)).score - 3) < 1e-8, '不涉及将帅解围时仍保留阵形循环扣分');
console.log(JSON.stringify({cases, choices: samples, rotation: true, noMutation: true, nativeDrawsPreserved: true, ordinaryRepetitionPenaltyPreserved: true}));

